import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();
        int[] x = new int[n];
        int h = 0;

        for (int i = 0; i < n; i++) {
            x[i] = sc.nextInt();
            if (x[i] > h) {
                h = x[i];
            }
        }

        StringBuilder sb = new StringBuilder();

        for (int level = h; level >= 1; level--) {
            for (int i = 0; i < n; i++) {
                if (i > 0) {
                    sb.append(' ');
                }
                sb.append(x[i] >= level ? '1' : '0');
            }
            sb.append('\n');
        }

        System.out.print(sb);
    }
}
